import RNA, random, multiprocessing as mp, time
target = ".....((((((((..((((....))))..)))).((((..(...)..)))).((((..(..(((.....)))..)..))))))))...................."
def worker(seed):
    random.seed(seed)
    for _ in range(300):
        start = ''.join(random.choice('ACGU') for _ in range(len(target)))
        seq, d = RNA.inverse_fold(start, target)
        if d == 0 and RNA.fold_compound(seq).mfe()[0] == target:
            return seq
    return None
if __name__ == '__main__':
    found = []
    with mp.Pool(64) as p:
        for r in p.imap_unordered(worker, range(2000)):
            if r:
                found.append(r)
                print('SOLVED', r, flush=True)
                if len(found) >= 1:
                    p.terminate(); break
    if not found:
        print('NONE')
EOF
